"""Export reference data for src/engine/redact.ts, generated by the Python implementation."""

import json
import logging
from pathlib import Path

from ffpr_common.redact import MASK, RedactingFilter, Redactor

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "test" / "fixtures" / "redact.json"

redactor = Redactor()
redactor.add("SECRETKEY123456")
redactor.add("abc")
plain = ["url?key=SECRETKEY123456&x=abc", "nothing to hide"]

record = logging.LogRecord("t", logging.INFO, __file__, 1, "GET %s", ("k=SECRETKEY123456",), None)
RedactingFilter(redactor).filter(record)

out = {
    "mask": MASK,
    "redact": [{"text": text, "expected": redactor(text)} for text in plain],
    "filter": {"format": "GET %s", "args": ["k=SECRETKEY123456"], "expected": record.getMessage()},
}

OUT.write_text(json.dumps(out, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
print(f"wrote {OUT}")
